#include <string>
#include <sstream>
#include <algorithm>
#include <boost/algorithm/string.hpp>

std::string convertMarkdownToHtml(const std::string& markdown) {
    std::stringstream htmlStream;

    // Headers
    auto headers = boost::split(std::vector<std::string>{}, markdown, [](char c) { return c == '#' || c == '\n'; });
    for (const auto& header : headers) {
        std::string level;
        while (!header.empty() && header.front() == '#') {
            level += "<h" + std::to_string(header.size() - 1) + ">";
            header.erase(header.begin());
        }
        htmlStream << level << boost::trim_copy(header) << "</" << level << ">\n";
    }

    // Bold and italic
    std::string text = boost::trim_copy(markdown);
    boost::replace_all(text, "**", "<strong>");
    boost::replace_all(text, "__", "<strong>");
    boost::replace_all(text, "*_", "<em>");
    boost::replace_all(text, "_*", "<em>");
    htmlStream << text << "</strong></em>\n";

    // Lists
    auto items = boost::split(std::vector<std::string>{}, text, [](char c) { return c == '-' || c == '+' || c == '*' || c == '\n'; });
    std::string listType;
    for (const auto& item : items) {
        if (item.empty()) {
            htmlStream << "</ul>\n";
            listType.clear();
            continue;
        }

        if (listType.empty()) {
            auto bullet = item.front();
            if (bullet == '*') {
                listType = "ul";
            } else if (bullet == '-') || bullet == '+') {
                listType = "ol";
            } else {
                htmlStream << boost::trim_copy(item);
                continue;
            }
            htmlStream << "<" << listType << ">\n";
        }

        htmlStream << "<li>" << boost::trim_copy(item.substr(1)) << "</li>\n";
    }

    // Links
    boost::replace_all(text, "[", "<a href='");
    boost::replace_all(text, "]", "'");

    htmlStream << boost::trim_copy(text);

    return htmlStream.str();
}
```

This implementation uses Boost libraries to split the markdown string into headers, lists, and other elements. It also relies on some string manipulation to convert basic markdown syntax (headers, bold/italic, lists, links) to HTML.

